&lt;ul&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;sub&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;You will lead an engineering team building the next-generation ETL features for the Databricks Lakeflow platform.&lt;/span&gt;&lt;/sub&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;
